{
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));
const L=s=>s.trim().split('\n').map(l=>l.split('|'));
const RAD={},RADS=[];
L(RAD_RAW.trim()+'\n'+RAD3_RAW.trim()).forEach(([k,hv,ng,so,note])=>{const r={k,hv,ng,so:+so,note};RAD[k]=r;RADS.push(r)});
const CH={},CHS=[];
L(CHAR_ALL_RAW).forEach(([c,py,hv,ng,st,cp,t,story])=>{const comps=cp.split(' ').filter(Boolean).map(p=>{const[k,role]=p.split(':');return{k,role}});const o={c,py,hv,ng,st,comps,t,story};CH[c]=o;CHS.push(o)});
const WORDS=L(WORD_ALL_RAW).map(([w,py,ng,ex,expy,exvi,lv])=>({w,py,ng,ex,expy,exvi,lv:+lv}));
const lvName=l=>'HSK'+l;
const FUN={};L(FUN_ALL_RAW).forEach(([c,t])=>{if(t)FUN[c]=t});
CHS.forEach(ch=>{const ls=WORDS.filter(w=>w.w.includes(ch.c)).map(w=>w.lv);ch.lv=ls.length?Math.min(...ls):9});
let LV=0;try{LV=+(JSON.parse(localStorage.getItem('chiet-tu-hsk-v1')||'{}').meta||{}).lv||0}catch(e){}const inLv=ch=>!LV||ch.lv===LV;
const byComp={};CHS.forEach(ch=>ch.comps.forEach(({k,role})=>{(byComp[k]=byComp[k]||[]);if(!byComp[k].some(x=>x.c===ch.c))byComp[k].push({c:ch.c,role})}));
const wordsOf=c=>WORDS.filter(w=>w.w.includes(c));
const ST={d:'Đơn thể',td:'Trên dưới',tp:'Trái phải',bq:'Bao quanh',bn:'Bao một phần'};
const RO={n:'gợi nghĩa',a:'gợi âm',h:'gợi hình'};
const norm=s=>String(s).normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d').replace(/Đ/g,'d').toLowerCase();
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[a[i],a[j]]=[a[j],a[i]]}return a};
const DAY=864e5,KEY='chiet-tu-hsk-v1';
let P={};try{P=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch(e){P={}}
P.cards=P.cards||{};P.meta=P.meta||{newPerDay:10,day:'',newToday:0};
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(P))}catch(e){}};
const today=()=>new Date().toISOString().slice(0,10);
const rollDay=()=>{if(P.meta.day!==today()){P.meta.day=today();P.meta.newToday=0}};
const isDue=c=>P.cards[c]&&P.cards[c].d<=Date.now();
const dueList=()=>CHS.filter(x=>isDue(x.c)).map(x=>x.c);
const newLeft=()=>{rollDay();return Math.max(0,P.meta.newPerDay-P.meta.newToday)};
function review(c,q){
  rollDay();const now=Date.now();let s=P.cards[c];
  if(!s){s={e:2.5,n:0,i:0,d:now};P.meta.newToday++}
  if(q<3){s.n=0;s.i=0;s.d=now+10*60e3}
  else{s.n++;s.i=s.n===1?1:s.n===2?(q===5?4:3):Math.round(s.i*s.e);if(q===3)s.i=Math.max(1,Math.round(s.i*.7));s.d=now+s.i*DAY}
  s.e=Math.max(1.3,s.e+.1-(5-q)*(.08+(5-q)*.02));s.l=now;P.cards[c]=s;save();badge();
}
const badge=()=>{$('#dueBadge').textContent=dueList().length+newLeft()};
let ZHV=null;
const isMandarin=v=>/^(zh|cmn)/i.test(v.lang)&&!/(HK|yue|MO)/i.test(v.lang)&&!/canton|粤|sin-ji|sinji/i.test(v.name);
const vScore=v=>{const n=v.name;let s=0;if(/natural|neural/i.test(n))s+=10;if(/premium/i.test(n))s+=8;if(/enhanced|cao cấp|nâng cao/i.test(n))s+=6;if(/online/i.test(n))s+=4;if(/google/i.test(n))s+=3;if(/xiaoxiao|xiaoyi|yunxi|yunyang|tingting|lili|li-mu|yu-shu|meijia|xiaochen/i.test(n))s+=2;if(/zh[-_]CN/i.test(v.lang))s+=1;if(v.localService===false)s+=1;return s};
const zhVoices=()=>{try{return speechSynthesis.getVoices().filter(isMandarin).sort((a,b)=>vScore(b)-vScore(a)||a.name.localeCompare(b.name))}catch(e){return[]}};
const BADV=new Set();
const localBest=vs=>vs.find(v=>v.localService!==false&&!BADV.has(v.voiceURI))||vs.find(v=>!BADV.has(v.voiceURI))||null;
const pickV=()=>{const vs=zhVoices();const saved=P.meta.voice&&!BADV.has(P.meta.voice)&&vs.find(v=>v.voiceURI===P.meta.voice);ZHV=saved||localBest(vs)||null};
const vLabel=v=>{const n=v.name.replace(/Microsoft |Google |\(Natural\)|Online|- Chinese \(Mainland\)|Chinese \(Simplified, PRC\)/g,' ').replace(/\s+/g,' ').trim();const tags=[];if(vScore(v)>=10)tags.push('tự nhiên');else if(vScore(v)>=6)tags.push('chất lượng cao');if(v.localService===false)tags.push('cần mạng, có thể không chạy');if(/TW/i.test(v.lang))tags.push('giọng Đài Loan');return n+(tags.length?' ('+tags.join(', ')+')':'')};
try{pickV();speechSynthesis.onvoiceschanged=()=>{pickV();if($('#v-tien-do').classList.contains('on'))renderProg()}}catch(e){}
const rate=()=>P.meta.rate||0.8;
const say1=(t,r)=>{const u=new SpeechSynthesisUtterance(t);u.lang=ZHV?ZHV.lang:'zh-CN';u.rate=r||rate();u.pitch=P.meta.pitch||1;if(ZHV)u.voice=ZHV;return u};
const ttsWarn=()=>{if(!ZHV&&!P.meta.ttsWarned){P.meta.ttsWarned=1;save();toast('Máy chưa có giọng đọc tiếng Trung, có thể không nghe được. Cài thêm giọng "Chinese (China)" trong cài đặt ngôn ngữ của máy.')}};
// Trình phát: đọc lần lượt từng câu, câu sau chỉ bắt đầu khi câu trước xong (tránh lỗi Chrome/Android bỏ hàng đợi)
const TTS={q:[],i:0,run:0,keep:[],wd:0,onStop:null};
const hl=el=>{document.querySelectorAll('.playing').forEach(x=>x.classList.remove('playing'));if(el){el.classList.add('playing');try{el.scrollIntoView({block:'nearest',behavior:'smooth'})}catch(e){}}};
const ttsStop=()=>{TTS.run++;TTS.q=[];clearTimeout(TTS.wd);clearTimeout(TTS.sw);try{if(speechSynthesis.speaking||speechSynthesis.pending)speechSynthesis.cancel()}catch(e){}hl(null);const f=TTS.onStop;TTS.onStop=null;if(f)f()};
const ttsNext=run=>{if(run!==TTS.run)return;if(TTS.i>=TTS.q.length){hl(null);const f=TTS.onStop;TTS.onStop=null;if(f)f();return}
  const it=TTS.q[TTS.i];const u=say1(it.t,it.r);TTS.keep=[u];let done=false,started=false;const vNow=ZHV;
  const fin=()=>{if(done||run!==TTS.run)return;done=true;clearTimeout(TTS.wd);clearTimeout(TTS.sw);TTS.i++;setTimeout(()=>ttsNext(run),it.gap||350)};
  const fallback=why=>{if(done||run!==TTS.run)return;done=true;clearTimeout(TTS.wd);clearTimeout(TTS.sw);
    if(vNow&&!it.retried){BADV.add(vNow.voiceURI);pickV();if(ZHV&&ZHV!==vNow){it.retried=1;toast('Giọng "'+vNow.name+'" không phát được ('+why+'). Đã chuyển sang giọng "'+ZHV.name+'".');try{speechSynthesis.cancel()}catch(e){}setTimeout(()=>ttsNext(run),200);return}}
    if(!it.retried){it.retried=1;try{speechSynthesis.cancel()}catch(e){}setTimeout(()=>ttsNext(run),250);return}
    toast('Không phát được âm thanh ('+why+'). Thử bấm lại, hoặc vào Tiến độ > Giọng đọc chọn giọng khác.');TTS.i++;setTimeout(()=>ttsNext(run),300)};
  u.onstart=()=>{started=true;clearTimeout(TTS.sw)};
  u.onend=fin;
  u.onerror=ev=>{const er=(ev&&ev.error)||'lỗi';if(er==='interrupted'||er==='canceled'){fin();return}fallback(er)};
  hl(it.el||null);
  clearTimeout(TTS.wd);TTS.wd=setTimeout(()=>{started?fin():fallback('không có tiếng')},3000+it.t.length*600);
  clearTimeout(TTS.sw);TTS.sw=setTimeout(()=>{if(!started&&!done&&!speechSynthesis.speaking)fallback('không có tiếng')},2500);
  try{speechSynthesis.speak(u);if(speechSynthesis.paused)speechSynthesis.resume()}catch(e){fallback('trình duyệt chặn')}};
const ttsPlay=(items,onStop,keepV)=>{try{if(!('speechSynthesis' in window)){toast('Trình duyệt này không hỗ trợ đọc. Hãy mở bằng Chrome, Safari hoặc Edge.');return}if(!keepV)pickV();ttsStop();TTS.q=items.filter(x=>x&&x.t).map(x=>Object.assign({},x));TTS.i=0;TTS.onStop=onStop||null;ttsNext(TTS.run);ttsWarn()}catch(e){toast('Trình duyệt này không hỗ trợ đọc.')}};
const speak=(t,r)=>{if(t)ttsPlay([{t,r}])};
const speakList=list=>ttsPlay(list.map(t=>({t})));
const toast=m=>{let t=document.getElementById('toast');if(!t){t=document.createElement('div');t.id='toast';document.body.appendChild(t)}t.textContent=m;t.classList.add('on');clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove('on'),4500)};
const SPK='<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9H4z" fill="currentColor"/><path d="M16 8.5a5 5 0 0 1 0 7M18.5 6a8.5 8.5 0 0 1 0 12" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round"/></svg>';
const spk=(t,label)=>'<button class="spk" data-say="'+esc(t)+'" aria-label="'+esc(label||('Nghe '+t))+'" title="Nghe">'+SPK+'</button>';
let STROKES=null;
const strokes=()=>STROKES||(STROKES=fetch('strokes.json').then(r=>r.json()).catch(()=>(typeof STROKE_DATA!=='undefined'?STROKE_DATA:{})));
const cssColor=(v,fb)=>{try{const e=document.createElement('span');e.style.color='var('+v+')';document.body.appendChild(e);const c=getComputedStyle(e).color;e.remove();return /^rgba?\(\d/.test(c)||/^#/.test(c)?c:fb}catch(x){return fb}};
const red=()=>cssColor('--red','#b8261a');
const inkC=()=>cssColor('--ink','#17181a');
const gridSvg='<svg class="grid" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><g stroke="var(--grid)" stroke-width=".5" stroke-dasharray="2 2" fill="none"><line x1="0" y1="0" x2="100" y2="100"/><line x1="100" y1="0" x2="0" y2="100"/><line x1="50" y1="0" x2="50" y2="100"/><line x1="0" y1="50" x2="100" y2="50"/></g></svg>';
function mountWriter(el,c,opt={}){
  el.innerHTML='';const w=el.clientWidth||260;
  try{return HanziWriter.create(el,c,Object.assign({width:w,height:w,padding:Math.round(w*.06),showOutline:true,strokeColor:inkC(),radicalColor:red(),outlineColor:'rgba(128,128,128,.25)',strokeAnimationSpeed:1.2,delayBetweenStrokes:180,charDataLoader:(ch,ok,err)=>{strokes().then(d=>d[ch]?ok(d[ch]):err('no data'))}},opt))}
  catch(e){el.innerHTML='<div class="hz" style="display:grid;place-items:center;height:100%;font-size:'+(w*.7)+'px">'+esc(c)+'</div>';return null}
}
const storyHtml=ch=>(FUN[ch.c]?'<div class="fun"><span class="tag">Mẹo nhớ</span>'+esc(FUN[ch.c])+'</div>':'<div class="fun" style="opacity:.75"><span class="tag">Mẹo nhớ</span>Chữ này chưa có mẹo vui, đang được bổ sung. Tạm nhớ theo phép ghép bộ ở trên.</div>')+'<div class="story '+ch.t+'"><span class="tag">'+(ch.t==='g'?'Chiết tự gốc':'Ghi chú')+'</span>'+esc(ch.story)+'</div>';
const PIC={};try{L(PIC_RAW).forEach(([k,bg,g,svg])=>{if(k&&svg){const q=(g||'').split(',');PIC[k]={bg,svg,x:+q[0]||20,y:+q[1]||20,size:+q[2]||60,col:q[3]||'#1a1a1a',w:+q[4]||70}}})}catch(e){}
const glyphSvg=k=>{const d=(typeof STROKE_DATA!=='undefined')&&STROKE_DATA[k];if(!d)return '<text x="50" y="72" font-size="56" text-anchor="middle" fill="#1d1d1f" stroke="#fff" stroke-width="3" paint-order="stroke" font-family="serif">'+esc(k)+'</text>';const s=60/1024,ps=d.strokes.map(x=>'<path d="'+x+'"/>').join('');return '<g transform="translate(20,'+(20+900*s)+') scale('+s+','+(-s)+')"><g fill="#fff" stroke="#fff" stroke-width="60" stroke-linejoin="round">'+ps+'</g><g fill="#1d1d1f">'+ps+'</g></g>'};
const medSvg=(k,p)=>{const d=(typeof STROKE_DATA!=='undefined')&&STROKE_DATA[k];if(!d||!d.medians)return glyphSvg(k);const sc=p.size/1024;const ps=d.medians.map(m=>'<path d="M'+m.map(q=>q[0]+' '+q[1]).join(' L')+'"/>').join('');return '<g transform="translate('+p.x+','+(p.y+900*sc)+') scale('+sc+','+(-sc)+')" fill="none" stroke="'+p.col+'" stroke-width="'+p.w+'" stroke-linecap="round" stroke-linejoin="round">'+ps+'</g>'};
const picSvg=(k,cls)=>{const p=PIC[k];if(!p)return '';return '<svg class="pic '+(cls||'')+'" viewBox="0 0 100 100" role="img" aria-label="'+esc(k)+'"><rect width="100" height="100" rx="12" fill="'+p.bg+'"/>'+p.svg+medSvg(k,p)+'</svg>'};
const tile=(k,role)=>{const r=RAD[k]||{};const ch=CH[k];return '<button class="tile '+role+(PIC[k]?' haspic':'')+'" data-rad="'+esc(k)+'">'+(PIC[k]?picSvg(k,'tp'):'<b class="hz">'+esc(k)+'</b>')+'<small>'+esc(r.hv||(ch&&ch.hv)||'')+'</small><small>'+esc(RO[role]||'')+'</small></button>'};
function eqHtml(ch){
  if(!ch.comps.length)return '<div class="eq"><span class="res hz">'+ch.c+'</span><span class="meta">Chữ đơn thể (tượng hình hoặc chỉ sự). Không tách thành bộ khác.</span></div>';
  const lay=ch.st==='td'?'td':'tp';
  return '<div class="eq"><div class="stackc '+lay+'">'+ch.comps.map(x=>tile(x.k,x.role)).join('')+'</div><span class="op">=</span><span class="res hz">'+ch.c+'</span></div><div class="legend"><span class="ln">gợi nghĩa</span><span class="la">gợi âm</span><span>gợi hình / ký hiệu</span></div>';
}
// ---------- Học chữ ----------
let cur='好',writer=null;
function renderList(){
  const q=norm($('#q').value.trim());
  const raw=$('#q').value.trim(),qq=q.replace(/\s/g,'');
  const rank=x=>{const p=norm(x.py).replace(/\s/g,''),h=norm(x.hv);if(x.c===raw||p===qq||h===q)return 0;if(p.startsWith(qq)||h.startsWith(q))return 1;if(norm(x.ng).split(/[,;() ]+/).includes(q))return 2;if(p.includes(qq)||h.includes(q)||norm(x.ng).includes(q)||raw.includes(x.c))return 3;return 9};
  const base=CHS.filter(inLv);const res=q?base.map(x=>[x,rank(x)]).filter(a=>a[1]<9).sort((a,b)=>a[1]-b[1]).map(a=>a[0]):base;
  $('#list').innerHTML=res.map(x=>'<button class="chip'+(x.c===cur?' on':'')+'" data-c="'+x.c+'" title="'+esc(x.hv+' · '+x.ng)+'">'+x.c+(P.cards[x.c]?'<i class="'+(isDue(x.c)?'due':'')+'"></i>':'')+'</button>').join('');
  $('#listNote').textContent=res.length+' chữ đơn'+(LV?' của '+lvName(LV):' của HSK 3.0, cấp 1 đến 9')+(LV>=7?' (HSK7-9 chính thức là một nhóm chung; tách 7, 8, 9 theo độ phổ biến của từ)':'')+'. Chấm xanh: đã học, chấm đỏ: đến hạn ôn.';
}
function renderCard(){
  const ch=CH[cur],SEQ=inLv(ch)?CHS.filter(inLv):CHS,i=SEQ.indexOf(ch);const ws=wordsOf(cur);
  const self=RAD[cur];const same=ch.comps.filter(x=>x.role!=='h').map(x=>x.k);
  const rel=[...new Set(same.flatMap(k=>(byComp[k]||[]).map(o=>o.c)))].filter(c=>c!==cur).slice(0,16);
  $('#card').innerHTML='<div class="card"><div><div class="sheet">'+gridSvg+'<div class="w" id="w"></div></div><div class="tools"><button id="bSpeak">Nghe</button><button id="bAnim">Xem nét</button><button id="bQuiz">Tập viết</button></div><p class="note" id="wNote">Nét màu đỏ trong hoạt ảnh là bộ thủ chính của chữ.</p></div>'+
  '<div>'+(PIC[ch.c]?picSvg(ch.c,'cardpic'):'')+'<div class="py">'+esc(ch.py)+'</div><div class="hv">'+esc(ch.hv)+'</div><div class="mean">'+esc(ch.ng)+'</div>'+
  '<p class="meta">'+lvName(ch.lv)+' · Cấu trúc: '+ST[ch.st]+(self?' · Bản thân chữ này là bộ thủ'+(self.so?' số '+self.so:''):'')+'</p>'+eqHtml(ch)+
  ''+storyHtml(ch)+''+
  (ws.length?'<div class="wh"><h2>Từ HSK có chữ '+ch.c+' ('+ws.length+')</h2><div class="row" style="margin:0"><label class="note cb"><input type="checkbox" id="cbEx"'+(P.meta.readEx?' checked':'')+'> đọc cả câu ví dụ</label><button class="spkall" id="bSayAll">'+SPK+' Nghe tất cả</button></div></div><ul class="words">'+ws.map(w=>'<li data-say="'+esc(w.w)+'"><div class="wrow">'+spk(w.w,'Nghe từ '+w.w)+'<button class="wz hz plain" data-say="'+esc(w.w)+'">'+w.w+'</button><span class="note">'+lvName(w.lv)+'</span> <b>'+esc(w.py)+'</b> · '+esc(w.ng)+'</div>'+(w.ex?'<div class="ex">'+spk(w.ex,'Nghe câu ví dụ')+'<span class="hz">'+esc(w.ex)+'</span> '+esc(w.expy)+' · '+esc(w.exvi)+'</div>':'')+'</li>').join('')+'</ul>':'')+
  (rel.length?'<h2>Chữ chung bộ</h2><div class="chips hz" style="max-height:none">'+rel.map(c=>'<button class="chip" data-c="'+c+'" title="'+esc(CH[c].hv)+'">'+c+'</button>').join('')+'</div>':'')+
  '<div class="nav2"><button id="bPrev"'+(i?'':' disabled')+'>Chữ trước</button><button id="bLearn" class="pri">'+(P.cards[cur]?'Đã học, ôn lại sau':'Đánh dấu đã học')+'</button><button id="bNext"'+(i<SEQ.length-1?'':' disabled')+'>Chữ sau</button></div></div></div>';
  writer=mountWriter($('#w'),cur);
  $('#bSpeak').onclick=()=>speak(ch.c);
  const sa=$('#bSayAll');if(sa){const lab=sa.innerHTML;let on=false;sa.onclick=()=>{if(on){ttsStop();return}
    const items=[];document.querySelectorAll('#card .words li').forEach((li,k)=>{const w=ws[k];items.push({t:w.w,el:li,gap:500});if($('#cbEx')&&$('#cbEx').checked&&w.ex)items.push({t:w.ex,el:li,gap:700})});
    on=true;sa.innerHTML='■ Dừng';sa.classList.add('on');ttsPlay(items,()=>{on=false;sa.innerHTML=lab;sa.classList.remove('on')})}}
  $('#bAnim').onclick=()=>{if(writer){writer.cancelQuiz&&writer.cancelQuiz();writer.animateCharacter()}};
  $('#bQuiz').onclick=()=>{if(!writer)return;$('#wNote').textContent='Viết từng nét theo đúng thứ tự vào ô. Sai 3 lần sẽ có gợi ý.';writer.hideCharacter();writer.quiz({onComplete:s=>{$('#wNote').textContent='Xong. Số lần sai: '+s.totalMistakes+'.'}})};
  $('#bPrev').onclick=()=>go(SEQ[i-1].c);$('#bNext').onclick=()=>go(SEQ[i+1].c);
  $('#bLearn').onclick=()=>{if(!P.cards[cur])review(cur,4);renderCard();renderList()};
}
function go(c){ttsStop();cur=c;renderList();renderCard();if(innerWidth<900)$('#card').scrollIntoView({behavior:'smooth'})}
// ---------- Bộ thủ ----------
let radSel='人',radF='kx';
const KX=L(KX_RAW).map(([so,c,vs,hv,ng,fun])=>{so=+so;const nt=so<=6?1:so<=29?2:so<=60?3:so<=94?4:so<=117?5:so<=146?6:so<=166?7:so<=175?8:so<=184?9:so<=194?10:so<=200?11:so<=204?12:so<=208?13:so<=210?14:so===211?15:so<=213?16:17;return{so,c,vs:vs.split(' ').filter(Boolean).map(v=>v.replace(/\(.*\)/,'')),vraw:vs,hv,ng,fun,nt}});
const KXV={};KX.forEach(k=>{KXV[k.c]=k;k.vs.forEach(v=>{if(!KXV[v])KXV[v]=k})});
const kxChars=k=>{const seen=new Set(),out=[];[k.c].concat(k.vs).forEach(f=>(byComp[f]||[]).forEach(x=>{if(!seen.has(x.c)){seen.add(x.c);out.push(x)}}));return out};
function renderRad(){
  if(radF==='pic'){
    $('#radGrid').innerHTML=Object.keys(PIC).map(k=>{const r=RAD[k]||{};const c=CH[k];return '<button class="rad picrad'+(k===radSel?' on':'')+'" data-rad="'+esc(k)+'">'+picSvg(k,'gp')+'<small>'+esc(r.hv||(c&&c.hv)||'')+' · '+esc(r.ng||(c&&c.ng)||'')+'</small></button>'}).join('');
  }else if(radF==='kx'){
    $('#radGrid').innerHTML=KX.map(k=>{const n=kxChars(k).length;const on=KXV[radSel]===k;return '<button class="rad kx'+(on?' on':'')+'" data-rad="'+esc(k.c)+'"><i>'+k.so+'</i><b class="hz">'+esc(k.c)+'</b>'+(k.vs.length?'<em class="hz">'+esc(k.vs.join(' '))+'</em>':'')+'<small>'+esc(k.hv)+(n?' · '+n+' chữ':'')+'</small></button>'}).join('');
  }else{
    const list=RADS.filter(r=>byComp[r.k]&&(radF==='all'||r.so===0)).sort((a,b)=>(byComp[b.k].length-byComp[a.k].length)||(a.so-b.so));
    $('#radGrid').innerHTML=list.map(r=>'<button class="rad'+(r.k===radSel?' on':'')+'" data-rad="'+esc(r.k)+'"><b class="hz">'+esc(r.k)+'</b><small>'+esc(r.hv)+' · '+byComp[r.k].length+' chữ</small></button>').join('');
  }
  const kx=KXV[radSel];
  const r=RAD[radSel]||(kx?{k:radSel,hv:kx.hv,ng:kx.ng,so:kx.so,note:''}:{k:radSel,hv:CH[radSel]?CH[radSel].hv:'',ng:CH[radSel]?CH[radSel].ng:'',so:0,note:''});
  const items=kx&&(radF==='kx'||radF==='pic')?kxChars(kx):(byComp[radSel]||[]);
  const grp=role=>{const a=items.filter(x=>x.role===role);return a.length?'<div class="group"><h3>'+(role==='n'?'Bộ này gợi nghĩa':role==='a'?'Thành phần này gợi âm':'Chỉ gợi hình / ký hiệu')+' ('+a.length+')</h3><div class="chips hz">'+a.map(x=>'<button class="chip" data-c="'+x.c+'" title="'+esc(CH[x.c].hv+' · '+CH[x.c].ng)+'">'+x.c+'</button>').join('')+'</div></div>':''};
  const head=kx&&(radF==='kx'||radF==='pic')
    ?'<div class="radinfo">'+(PIC[radSel]?picSvg(radSel,'bigpic'):PIC[kx.c]?picSvg(kx.c,'bigpic'):'<div class="big hz">'+esc(kx.c)+'</div>')+'<div><div class="hv">'+kx.so+'. '+esc(kx.hv)+'</div><div class="mean" style="margin:0">'+esc(kx.ng)+'</div><p class="meta" style="margin:4px 0 0">'+kx.nt+' nét'+(kx.vs.length?' · Biến thể: <span class="hz" style="font-size:20px">'+esc(kx.vraw)+'</span>':'')+(CH[kx.c]?' · Cũng là một chữ '+lvName(CH[kx.c].lv):'')+'</p><div class="row" style="margin-top:6px">'+spk(kx.c,'Nghe bộ '+kx.c)+'<button id="kxPrev"'+(kx.so>1?'':' disabled')+'>Bộ trước</button><button id="kxNext"'+(kx.so<214?'':' disabled')+'>Bộ sau</button></div></div></div>'+(kx.fun?'<div class="fun"><span class="tag">Mẹo nhớ</span>'+esc(kx.fun)+'</div>':'')+(items.length?'':'<p class="note">Bộ này ít gặp, chưa có chữ nào trong danh sách HSK chứa nó.</p>')
    :'<div class="radinfo">'+(PIC[r.k]?picSvg(r.k,'bigpic'):'<div class="big hz">'+esc(r.k)+'</div>')+'<div><div class="hv">'+esc(r.hv)+'</div><div class="mean" style="margin:0">'+esc(r.ng)+'</div><p class="meta" style="margin:4px 0 0">'+(r.so?'Bộ số '+r.so+' trong 214 bộ Khang Hy':'Thành phần, không thuộc 214 bộ')+(r.note?' · '+esc(r.note):'')+(CH[r.k]?' · Cũng là một chữ '+lvName(CH[r.k].lv):'')+'</p></div></div>'+(kx&&kx.fun?'<div class="fun"><span class="tag">Mẹo nhớ bộ '+esc(kx.c)+'</span>'+esc(kx.fun)+'</div>':'');
  $('#radInfo').innerHTML=head+grp('n')+grp('a')+grp('h');
  const go2=d=>{const k=KX[kx.so-1+d];if(k){radSel=k.c;renderRad();const b=document.querySelector('#radGrid .rad.on');if(b)try{b.scrollIntoView({block:'nearest'})}catch(e){}}};
  const pv=$('#kxPrev'),nx=$('#kxNext');if(pv)pv.onclick=()=>go2(-1);if(nx)nx.onclick=()=>go2(1);
}
// ---------- Luyện tập ----------
let mode='mix',Q=null;
function queue(){const pl=LV||0,ok=c=>!pl||CH[c].lv===pl;const due=dueList().filter(ok).sort((a,b)=>P.cards[a].d-P.cards[b].d);const fresh=CHS.filter(x=>!P.cards[x.c]&&ok(x.c)).slice(0,newLeft()).map(x=>x.c);return due.concat(fresh)}
function nextQ(){
  let qs=queue();
  if(mode==='ghep')qs=qs.filter(c=>CH[c].comps.length>1);
  if(!qs.length){Q=null;return renderQuiz()}
  const c=qs[0],ch=CH[c];let type=mode;
  if(mode==='mix'){const t=['the','c2m','m2c','nghe'];if(ch.comps.length>1)t.push('ghep','ghep');type=t[Math.random()*t.length|0]}
  if(mode==='trac')type=['c2m','m2c','nghe'][Math.random()*3|0];
  Q={c,type,isNew:!P.cards[c],done:false,picked:[]};
  if(type==='ghep'){const own=ch.comps.map(x=>x.k);const pool=shuffle(Object.keys(byComp).filter(k=>!own.includes(k))).slice(0,Math.max(3,6-own.length));Q.opts=shuffle([...new Set(own)].concat(pool))}
  if(type==='c2m'||type==='m2c'||type==='nghe'){Q.opts=shuffle([c].concat(shuffle(CHS.filter(x=>x.c!==c&&x.ng!==ch.ng).map(x=>x.c)).slice(0,3)))}
  renderQuiz();if(type==='nghe')setTimeout(()=>speak(c),300);
}
const fbWords=ch=>{const ws=wordsOf(ch.c).slice(0,4);return ws.length?'<div class="words mini">'+ws.map(w=>'<div class="wrow">'+spk(w.w)+'<span class="hz wz">'+w.w+'</span> '+esc(w.py)+' · '+esc(w.ng)+'</div>').join('')+'</div>':''};
function feedback(ok){const ch=CH[Q.c];return '<div class="fb"><p><b style="color:var('+(ok?'--ok':'--red')+')">'+(ok?'Chính xác.':'Chưa đúng.')+'</b> '+spk(ch.c)+' <span class="hz" style="font-size:28px">'+ch.c+'</span> '+esc(ch.py)+' · '+esc(ch.hv)+' · '+esc(ch.ng)+'</p>'+eqHtml(ch)+''+storyHtml(ch)+fbWords(ch)+'<button class="pri" id="bNextQ" style="width:100%">Câu tiếp</button></div>'}
function renderQuiz(){
  const modes=[['mix','Trộn'],['the','Thẻ nhớ'],['ghep','Ghép bộ'],['trac','Trắc nghiệm']];
  let h='<h1>Luyện tập</h1><p class="meta">Hôm nay còn '+dueList().length+' chữ đến hạn ôn và '+newLeft()+' chữ mới. Lịch ôn tính theo thuật toán SM-2.</p><div class="row filters" id="modes">'+modes.map(([k,t])=>'<button data-m="'+k+'" class="'+(mode===k?'on':'')+'">'+t+'</button>').join('')+'</div><p class="note">Đang luyện: '+(LV?lvName(LV):'mọi cấp')+'. Đổi cấp ở thanh trên cùng.</p><div style="height:16px"></div>';
  if(!Q){h+='<div class="qbox"><p class="mean">Hết bài cho hôm nay.</p><p class="meta">Chữ ôn sai sẽ quay lại sau 10 phút. Muốn học thêm chữ mới, tăng số chữ mới mỗi ngày ở mục Tiến độ.</p><button id="bMore">Học thêm 5 chữ mới</button></div>';$('#quiz').innerHTML=h;bindQuiz();return}
  const ch=CH[Q.c];h+='<div class="qbox">'+(Q.isNew?'<p class="note">Chữ mới</p>':'');
  if(Q.type==='the'){
    h+='<div class="qbig hz">'+ch.c+'</div>';
    h+=Q.done?'<div class="fb"><p class="py">'+esc(ch.py)+' <span class="hv">'+esc(ch.hv)+'</span></p><p class="mean">'+esc(ch.ng)+'</p>'+eqHtml(ch)+''+storyHtml(ch)+fbWords(ch)+'</div><div class="grades"><button data-g="0">Quên</button><button data-g="3">Khó</button><button data-g="4">Nhớ</button><button data-g="5">Dễ</button></div>':'<p class="meta">Nhớ lại âm, nghĩa và các bộ ghép thành chữ này.</p><button class="pri" id="bFlip" style="width:100%">Lật thẻ</button>';
  }else if(Q.type==='ghep'){
    h+='<p class="meta">Chọn các bộ ghép thành chữ có nghĩa:</p><p class="mean" style="margin:0"><b>'+esc(ch.ng)+'</b></p><p class="py" style="font-size:20px">'+esc(ch.py)+' · <span class="hv" style="font-size:18px">'+esc(ch.hv)+'</span></p><p class="note">'+ST[ch.st]+', '+ch.comps.length+' thành phần</p>';
    h+='<div class="pick">'+Q.opts.map(k=>'<button class="tile'+(Q.picked.includes(k)?' sel':'')+'" data-p="'+esc(k)+'"'+(Q.done?' disabled':'')+'><b class="hz">'+esc(k)+'</b><small>'+esc((RAD[k]||{}).hv||'')+'</small></button>').join('')+'</div>';
    h+=Q.done?feedback(Q.ok):'<button class="pri" id="bCheck" style="width:100%;margin-top:16px">Kiểm tra</button>';
  }else{
    const ask=Q.type==='c2m'?'<div class="qbig hz">'+ch.c+'</div><p class="meta">Chữ này nghĩa là gì?</p>':Q.type==='m2c'?'<p class="mean"><b>'+esc(ch.ng)+'</b></p><p class="hv">'+esc(ch.hv)+'</p><p class="meta">Chọn chữ đúng</p>':'<button id="bReplay" style="min-height:80px;width:160px;font-size:20px">Nghe lại</button><p class="meta">Nghe và chọn chữ đúng</p>';
    h+=ask+'<div class="opts">'+Q.opts.map(c=>{const cls=Q.done?(c===Q.c?'right':c===Q.ans?'wrong':''):'';return '<button data-o="'+c+'" class="'+(Q.type==='c2m'?'':'hz ')+cls+'"'+(Q.done?' disabled':'')+'>'+(Q.type==='c2m'?esc(CH[c].ng):c)+'</button>'}).join('')+'</div>';
    if(Q.done)h+=feedback(Q.ok);
  }
  $('#quiz').innerHTML=h+'</div>';bindQuiz();
}
function bindQuiz(){
  document.querySelectorAll('#modes button').forEach(b=>b.onclick=()=>{mode=b.dataset.m;nextQ()});
  const on=(id,f)=>{const e=$(id);if(e)e.onclick=f};
  on('#bMore',()=>{P.meta.newToday=Math.max(0,P.meta.newToday-5);save();badge();nextQ()});
  on('#bFlip',()=>{Q.done=true;speak(Q.c);renderQuiz()});
  on('#bReplay',()=>speak(Q.c));on('#bNextQ',nextQ);
  on('#bCheck',()=>{const own=[...new Set(CH[Q.c].comps.map(x=>x.k))].sort().join();Q.ok=Q.picked.slice().sort().join()===own;Q.done=true;review(Q.c,Q.ok?4:1);renderQuiz()});
  document.querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>{review(Q.c,+b.dataset.g);nextQ()});
  document.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>{const k=b.dataset.p;Q.picked=Q.picked.includes(k)?Q.picked.filter(x=>x!==k):Q.picked.concat(k);renderQuiz()});
  document.querySelectorAll('[data-o]').forEach(b=>b.onclick=()=>{Q.ans=b.dataset.o;Q.ok=Q.ans===Q.c;Q.done=true;review(Q.c,Q.ok?4:1);renderQuiz()});
}
// ---------- Tiến độ ----------
function renderProg(){
  const cs=Object.keys(P.cards).filter(c=>CH[c]);const master=cs.filter(c=>P.cards[c].i>=21).length;const learning=cs.length-master;const fresh=CHS.length-cs.length;
  const hard=cs.filter(c=>P.cards[c].e<2.3).sort((a,b)=>P.cards[a].e-P.cards[b].e).slice(0,20);
  const pct=n=>(n/CHS.length*100).toFixed(1)+'%';
  $('#prog').innerHTML='<h1>'+cs.length+' / '+CHS.length+' chữ đã vào lịch ôn</h1><p class="meta">'+[1,2,3,4,5,6,7,8,9].map(l=>lvName(l)+': '+cs.filter(c=>CH[c].lv===l).length+' / '+CHS.filter(x=>x.lv===l).length).join(' · ')+'</p>'+
  '<div class="bar"><span style="width:'+pct(master)+';background:var(--ok)"></span><span style="width:'+pct(learning)+';background:var(--blue)"></span></div><p class="note">Xanh lá: thành thạo (khoảng ôn từ 21 ngày). Xanh lam: đang học. Xám: chưa học.</p>'+
  '<div class="stats"><div class="stat"><b>'+dueList().length+'</b>đến hạn ôn</div><div class="stat"><b>'+learning+'</b>đang học</div><div class="stat"><b>'+master+'</b>thành thạo</div><div class="stat"><b>'+fresh+'</b>chưa học</div></div>'+
  (hard.length?'<h2>Chữ hay quên</h2><div class="chips hz" style="max-height:none">'+hard.map(c=>'<button class="chip" data-c="'+c+'">'+c+'</button>').join('')+'</div>':'')+
  '<h2>Cài đặt</h2><label class="row">Số chữ mới mỗi ngày <select id="npd" class="full" style="width:auto">'+[5,10,15,20,30].map(n=>'<option'+(n===P.meta.newPerDay?' selected':'')+'>'+n+'</option>').join('')+'</select></label>'+
  '<h2>Giọng đọc</h2>'+(()=>{const vs=zhVoices();return vs.length?'<div class="vlist">'+vs.map(v=>'<label class="vopt'+(ZHV&&v.voiceURI===ZHV.voiceURI?' on':'')+'"><input type="radio" name="vo" value="'+esc(v.voiceURI)+'"'+(ZHV&&v.voiceURI===ZHV.voiceURI?' checked':'')+'><span>'+esc(vLabel(v))+'</span><button type="button" class="spk" data-try="'+esc(v.voiceURI)+'" aria-label="Thử giọng '+esc(v.name)+'">'+SPK+'</button></label>').join('')+'</div>':'<p class="note">Chưa thấy giọng tiếng Trung trên máy này.</p>'})()+
  '<div class="row filters" id="rateF"><span class="note">Tốc độ</span>'+[[0.6,'Chậm'],[0.8,'Vừa'],[1,'Bình thường']].map(([r,t])=>'<button data-rate="'+r+'" class="'+(rate()===r?'on':'')+'">'+t+'</button>').join('')+'</div>'+
  '<div class="row filters"><span class="note">Cao độ</span>'+[[0.9,'Trầm'],[1,'Chuẩn'],[1.15,'Trong']].map(([r,t])=>'<button data-pitch="'+r+'" class="'+((P.meta.pitch||1)===r?'on':'')+'">'+t+'</button>').join('')+'</div>'+
  '<details class="vhelp"><summary>Cách cài thêm giọng hay (như Samantha của tiếng Anh)</summary><p><b>iPhone, iPad:</b> Cài đặt > Trợ năng > Nội dung được đọc > Giọng nói > Tiếng Trung (Trung Quốc đại lục). Tải giọng <b>Lili</b> hoặc <b>Tingting</b> bản <b>Cao cấp (Premium)</b> hay <b>Nâng cao (Enhanced)</b>. Đây là nhóm giọng cùng loại với Samantha, nghe tự nhiên hơn hẳn bản mặc định. Tải xong mở lại trang và chọn giọng đó ở trên.</p><p><b>Mac:</b> Cài đặt hệ thống > Trợ năng > Nội dung được đọc > Giọng hệ thống > Quản lý giọng, chọn Tiếng Trung, tải Lili hoặc Tingting bản Premium.</p><p><b>Máy tính Windows:</b> mở trang bằng trình duyệt <b>Microsoft Edge</b>. Edge có sẵn giọng thần kinh <b>Xiaoxiao</b>, <b>Xiaoyi</b>, <b>Yunxi</b> (ghi chú "tự nhiên"), hay nhất trong các lựa chọn, nhưng cần có mạng.</p><p><b>Android:</b> Cài đặt > Ngôn ngữ > Chuyển văn bản thành giọng nói > chọn công cụ của Google > Cài đặt dữ liệu giọng nói > Tiếng Trung (Trung Quốc), tải gói chất lượng cao. Mở trang bằng Chrome.</p></details>'+
  '<h2>Sao lưu tiến độ</h2><p class="meta">Tiến độ lưu trong trình duyệt đang mở file này. Muốn chuyển sang máy khác, tải file sao lưu rồi bấm Nhập từ file ở máy kia.</p><div class="row"><button id="bDl" class="pri">Tải file sao lưu</button><button type="button" id="bPick">Nhập từ file</button><input type="file" id="fImp" accept=".json,application/json" hidden></div><textarea id="exp" readonly>'+esc(JSON.stringify(P))+'</textarea><div class="row"><button id="bCopy">Chép mã</button><span class="note" id="cpNote"></span></div>'+
  '<textarea id="imp" placeholder="Hoặc dán mã sao lưu vào đây"></textarea><div class="row"><button id="bImp">Nhập tiến độ</button><button id="bReset">Xóa toàn bộ tiến độ</button><span class="note" id="impNote"></span></div>';
  const demo='你好！欢迎你来学习汉语。';
  document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{P.meta.rate=+b.dataset.rate;save();renderProg();speak(demo)});
  document.querySelectorAll('[data-pitch]').forEach(b=>b.onclick=()=>{P.meta.pitch=+b.dataset.pitch;save();renderProg();speak(demo)});
  document.querySelectorAll('input[name=vo]').forEach(r=>r.onchange=()=>{P.meta.voice=r.value;save();pickV();renderProg();speak(demo)});
  document.querySelectorAll('[data-try]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();const v=zhVoices().find(x=>x.voiceURI===b.dataset.try);if(!v)return;BADV.delete(v.voiceURI);ZHV=v;ttsPlay([{t:demo}],()=>{pickV()},true)});
  $('#npd').onchange=e=>{P.meta.newPerDay=+e.target.value;save();badge()};
  $('#bCopy').onclick=()=>{const t=$('#exp');t.select();(navigator.clipboard?navigator.clipboard.writeText(t.value):Promise.reject()).then(()=>$('#cpNote').textContent='Đã chép.',()=>$('#cpNote').textContent='Đã bôi đen, bấm Ctrl+C để chép.')};
  $('#bDl').onclick=()=>{try{const b=new Blob([JSON.stringify(P)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='chiet-tu-tien-do-'+today()+'.json';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},800);$('#cpNote').textContent='Đã tải file sao lưu.'}catch(e){$('#cpNote').textContent='Không tải được, hãy dùng nút Chép mã.'}};
  $('#bPick').onclick=()=>$('#fImp').click();
  $('#fImp').onchange=e=>{const f=e.target.files[0];if(!f)return;f.text().then(t=>{$('#imp').value=t;$('#bImp').click()})};
  $('#bImp').onclick=()=>{try{const o=JSON.parse($('#imp').value);if(!o.cards)throw 0;P=o;P.meta=P.meta||{newPerDay:10,day:'',newToday:0};save();badge();renderProg();$('#impNote').textContent='Đã nhập.'}catch(e){$('#impNote').textContent='Mã không hợp lệ.'}};
  let armed=false;$('#bReset').onclick=e=>{if(!armed){armed=true;e.target.textContent='Bấm lần nữa để xác nhận xóa';return}P={cards:{},meta:{newPerDay:P.meta.newPerDay,day:'',newToday:0}};save();badge();renderProg()};
}
// ---------- Điều hướng ----------
const VIEWS=['hoc','bo-thu','luyen','tien-do'];
function setLV(l){LV=l;P.meta.lv=l;save();document.querySelectorAll('#lvF button').forEach(b=>b.classList.toggle('on',+b.dataset.l===l));const v=location.hash.slice(1)||'hoc';if(v==='hoc'){renderList();const f=CHS.find(inLv);if(f&&!inLv(CH[cur])){cur=f.c;renderCard()}}if(v==='luyen'){Q=null;nextQ()}if(v==='tien-do')renderProg();badge()}
function route(){
  try{ttsStop()}catch(e){}
  const v=VIEWS.includes(location.hash.slice(1))?location.hash.slice(1):'hoc';
  VIEWS.forEach(x=>$('#v-'+x).classList.toggle('on',x===v));
  document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('on',a.dataset.v===v));
  if(v==='hoc'){renderList();renderCard()}if(v==='bo-thu')renderRad();if(v==='luyen'&&!Q)nextQ();if(v==='tien-do')renderProg();
}
document.addEventListener('click',e=>{
  const sy=e.target.closest('[data-say]');if(sy){const li=sy.closest('li');ttsPlay([{t:sy.dataset.say,el:li&&li.closest('#card')?li:null}]);return}
  const cb=e.target.closest('#cbEx');if(cb){P.meta.readEx=cb.checked;save();return}
  const c=e.target.closest('[data-c]');if(c){cur=c.dataset.c;if(location.hash!=='#hoc')location.hash='hoc';else go(cur);return}
  const r=e.target.closest('[data-rad]');if(r){radSel=r.dataset.rad;if(location.hash!=='#bo-thu')location.hash='bo-thu';else renderRad();scrollTo({top:0,behavior:'smooth'});return}
  const lb=e.target.closest('#lvF button');if(lb){setLV(+lb.dataset.l);return}
  const f=e.target.closest('#radFilter button');if(f){radF=f.dataset.f;document.querySelectorAll('#radFilter button').forEach(b=>b.classList.toggle('on',b===f));renderRad()}
});
$('#q').addEventListener('input',renderList);
addEventListener('hashchange',route);
let rt;addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(()=>{if($('#v-hoc').classList.contains('on'))writer=mountWriter($('#w'),cur)},250)});
rollDay();document.querySelectorAll('#lvF button').forEach(b=>b.classList.toggle('on',+b.dataset.l===LV));if(LV&&!inLv(CH[cur])){const f=CHS.find(inLv);if(f)cur=f.c}badge();route();strokes();
}

;if('serviceWorker' in navigator){window.addEventListener('load',()=>{navigator.serviceWorker.register('sw.js').catch(()=>{})})}